function validate(input) {
  const [spec, cancelledAt] = input;
  if (cancelledAt !== null && (!Number.isInteger(cancelledAt) || cancelledAt < 0 || cancelledAt > 1000)) return 'cancelledAt must be null or an integer from 0 to 1000.';
  if (!spec || typeof spec !== 'object' || Array.isArray(spec)) return 'generator must be an object such as { "yields": [{ "t": 100, "resolve": 1 }] }.';
  const fields = ['yields', 'catch', 'afterCatch', 'returns', 'throws'];
  if (Object.keys(spec).some((key) => !fields.includes(key))) return 'generator may only have yields, catch, afterCatch, returns and throws.';
  const plain = (value) => (Number.isInteger(value) && value >= -1000 && value <= 1000) || (typeof value === 'string' && value.length <= 30);
  const badSteps = (list, name) => {
    if (!Array.isArray(list) || list.length > 10) return `${name} must be a list of at most 10 promises.`;
    for (const step of list) {
      if (!step || typeof step !== 'object' || Array.isArray(step) || Object.keys(step).some((key) => !['t', 'resolve', 'reject'].includes(key)) || ('resolve' in step && 'reject' in step)) return `Each promise in ${name} is { t, resolve } or { t, reject }.`;
      if (step.t === null && ('resolve' in step || 'reject' in step)) return 'A promise with t: null never settles, so it takes no resolve or reject.';
      if (step.t !== null && (!Number.isInteger(step.t) || step.t < 0 || step.t > 1000)) return `Each promise in ${name} needs a t from 0 to 1000, or null.`;
      if (('resolve' in step && !plain(step.resolve)) || ('reject' in step && !plain(step.reject))) return 'Values must be integers from -1000 to 1000 or strings of at most 30 characters.';
    }
    return null;
  };
  const bad = badSteps(spec.yields, 'yields') ?? (spec.afterCatch === undefined ? null : badSteps(spec.afterCatch, 'afterCatch'));
  if (bad) return bad;
  if (spec.catch !== undefined && typeof spec.catch !== 'boolean') return 'catch must be true or false.';
  if (spec.afterCatch !== undefined && spec.catch !== true) return 'afterCatch needs catch: true.';
  if ('returns' in spec && 'throws' in spec) return 'Give at most one of returns and throws.';
  if (('returns' in spec && !plain(spec.returns)) || ('throws' in spec && !plain(spec.throws))) return 'returns and throws must be integers from -1000 to 1000 or strings of at most 30 characters.';
  // Follow the timeline: rule out ties with cancel() and further yields after a caught cancellation.
  let time = 0;
  let steps = spec.yields;
  let guarded = spec.catch === true;
  for (let i = 0; i < steps.length; i++) {
    if (steps[i].t === null && cancelledAt === null) return 'A promise with t: null never settles; give a cancelledAt that interrupts it.';
    const settle = steps[i].t === null ? Infinity : time + steps[i].t;
    if (cancelledAt !== null && steps[i].t > 0 && cancelledAt === settle) return 'cancelledAt falls exactly when a promise settles; move it by 1 ms.';
    if (cancelledAt !== null && cancelledAt < settle) {
      if (guarded && (spec.afterCatch ?? []).length > 0) return 'A generator that catches "Cancelled" must not yield again: drop afterCatch or move cancelledAt.';
      return null;
    }
    time = settle;
    if ('reject' in steps[i]) {
      if (!guarded) return null;
      guarded = false;
      steps = spec.afterCatch ?? [];
      i = -1;
    }
  }
  return null;
}

