function adapt(input, solve, kit) {
  const [spec, cancelledAt] = input;
  const show = (value) => value === undefined ? 'undefined' : JSON.stringify(value);
  let count = 0;
  const makePromise = (step) => {
    const index = ++count;
    if (step.t === null) {
      kit.trace(`The generator yields promise ${index}, which never settles`);
      return new Promise(() => {});
    }
    kit.trace(`The generator yields promise ${index}, which ${'reject' in step ? `rejects with ${show(step.reject)}` : `resolves with ${show(step.resolve)}`} after ${step.t} ms`);
    const promise = new Promise((resolve, reject) => {
      const settle = () => {
        kit.trace(`Promise ${index} settles`);
        if ('reject' in step) reject(step.reject);
        else resolve(step.resolve);
      };
      if (step.t > 0) setTimeout(settle, step.t);
      else settle();
    });
    promise.catch(() => {});
    return promise;
  };
  const tasks = function* () {
    let total = 0;
    const run = function* (steps) {
      for (const step of steps) {
        let received;
        try {
          received = yield makePromise(step);
        } catch (error) {
          kit.trace(`${show(error)} is thrown into the generator`);
          throw error;
        }
        kit.trace(`The generator is sent ${show(received)}`);
        if (typeof received === 'number') total += received;
      }
    };
    if (spec.catch) {
      try {
        yield* run(spec.yields);
      } catch (error) {
        kit.trace(`The generator catches ${show(error)}`);
        yield* run(spec.afterCatch ?? []);
      }
    } else yield* run(spec.yields);
    if ('throws' in spec) {
      kit.trace(`The generator throws ${show(spec.throws)}`);
      throw spec.throws;
    }
    const result = 'returns' in spec ? spec.returns : total;
    kit.trace(`The generator returns ${show(result)}`);
    return result;
  };
  kit.trace('cancellable(generator) is called');
  const pair = solve(tasks());
  if (!Array.isArray(pair) || pair.length !== 2 || typeof pair[0] !== 'function' || !pair[1] || typeof pair[1].then !== 'function') throw new Error('cancellable must return [cancel, promise].');
  const [cancel, promise] = pair;
  if (cancelledAt !== null) setTimeout(() => {
    kit.trace('cancel() is called');
    cancel();
  }, cancelledAt);
  return promise.then((value) => {
    kit.trace(`The promise resolves with ${show(value)}`);
    return { resolved: value };
  }, (error) => {
    const rejected = error instanceof Error ? String(error) : error;
    kit.trace(`The promise rejects with ${show(rejected)}`);
    return { rejected };
  });
}

