function cancellable(generator) {
  let cancel = null;
  const cancelled = new Promise((resolve, reject) => {
    cancel = () => reject('Cancelled');
  });
  cancelled.catch(() => {});
  const promise = (async () => {
    let step = generator.next();
    while (!step.done) {
      let failed = false;
      let received;
      try {
        received = await Promise.race([step.value, cancelled]);
      } catch (error) {
        failed = true;
        received = error;
      }
      step = failed ? generator.throw(received) : generator.next(received);
    }
    return step.value;
  })();
  return [cancel, promise];
}

