function cancellable(generator) {
  // Callback style: each yielded promise gets a one-shot handler, and cancel() fires the pending one early.
  let finished = false;
  let interrupt = null;
  let settle = null;
  const promise = new Promise((resolve, reject) => {
    settle = { resolve, reject };
  });
  const advance = (method, argument) => {
    let step;
    try {
      step = generator[method](argument);
    } catch (error) {
      finished = true;
      settle.reject(error);
      return;
    }
    if (step.done) {
      finished = true;
      settle.resolve(step.value);
      return;
    }
    let active = true;
    const once = (nextMethod, value) => {
      if (!active) return;
      active = false;
      advance(nextMethod, value);
    };
    interrupt = () => once('throw', 'Cancelled');
    Promise.resolve(step.value).then((value) => once('next', value), (error) => once('throw', error));
  };
  advance('next', undefined);
  const cancel = () => {
    if (!finished && interrupt) interrupt();
  };
  return [cancel, promise];
}

