function generate(rand, size) {
  const small = size === 'small';
  const pick = (max) => Math.floor(rand() * (max + 1));
  const value = () => rand() < 0.75 ? pick(small ? 10 : 2000) - (small ? 3 : 1000) : ['Hello', 'Oops', 'Done', 'Boom'][pick(3)];
  const steps = (length) => Array.from({ length }, () => {
    if (rand() < 0.06) return { t: null };
    const t = rand() < 0.4 ? 0 : 1 + pick(small ? 60 : 300);
    const roll = rand();
    if (roll < 0.15) return { t, reject: value() };
    if (roll < 0.3) return { t };
    return { t, resolve: value() };
  });
  // Same timeline rules as the validator: no tie with cancel(), no yield after a caught cancellation.
  const fair = (spec, cancelledAt) => {
    let time = 0, list = spec.yields, guarded = spec.catch === true;
    for (let i = 0; i < list.length; i++) {
      if (list[i].t === null && cancelledAt === null) return false;
      const settle = list[i].t === null ? Infinity : time + list[i].t;
      if (cancelledAt !== null && list[i].t > 0 && cancelledAt === settle) return false;
      if (cancelledAt !== null && cancelledAt < settle) return !(guarded && (spec.afterCatch ?? []).length > 0);
      time = settle;
      if ('reject' in list[i]) {
        if (!guarded) return true;
        guarded = false;
        list = spec.afterCatch ?? [];
        i = -1;
      }
    }
    return true;
  };
  for (;;) {
    const spec = { yields: steps(small ? pick(4) : 4 + pick(6)) };
    if (rand() < 0.5) {
      spec.catch = true;
      if (rand() < 0.6) spec.afterCatch = steps(small ? pick(3) : 1 + pick(5));
    }
    const ending = rand();
    if (ending < 0.2) spec.returns = value();
    else if (ending < 0.35) spec.throws = value();
    const cancelledAt = rand() < 0.3 ? null : pick(small ? 150 : 1000);
    if (fair(spec, cancelledAt)) return [spec, cancelledAt];
  }
}
